// How it works: a dense, contrasting band right after the hero — three airy steps on the inverse
// background, each step number drawn by the code on one baseline with its title (T17 process rows);
// the layout steps down diagonally on wide screens so it never reads as three equal tiles.
import { LazyMotion, domAnimation, m } from "motion/react";

type Step = {
  title: string;
  text: string;
};

export type BookingHowItWorksProps = {
  heading: string;
  steps: Step[];
};

export default function BookingHowItWorks({ heading, steps }: BookingHowItWorksProps) {
  return (
    <section className="bg-inverse font-sans text-inverse-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="max-w-text font-display text-h1 font-bold text-balance wrap-break-word">{heading}</h2>
        <LazyMotion features={domAnimation}>
          <ol className="mt-12 grid gap-10 md:grid-cols-3 md:gap-x-gutter lg:gap-x-16">
            {steps.map((step, i) => {
              const offset = i === 2 ? "lg:mt-14" : i === 1 ? "lg:mt-7" : "";
              const content = (
                <li key={step.title} className={`min-w-0 ${offset}`}>
                  <div className="flex items-baseline gap-3 border-t border-inverse-foreground/30 pt-5">
                    <span
                      aria-hidden="true"
                      className="shrink-0 font-display text-h3 font-bold tabular-nums text-inverse-foreground/50"
                >
                    {String(i + 1)}
                  </span>
                <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                  {step.title}
                </h3>
              </div>
              <p className="mt-2 pl-8 max-w-text text-body text-pretty text-inverse-foreground/80">
                {step.text}
              </p>
            </li>
          );
          return content;
        })}
      </ol>
      </LazyMotion>
      </div>
    </section>
  );
}

