// Booking «questions»: a dense short section before the form — the heading and the action on one
// top line, then three question–answer pairs laid out in two columns over card surfaces with a heavy
// rule between them (catalog D2 Q&A grid, T17). Own composition, texts from props only.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

type QA = { q: string; a: string };
type Link = { label: string; href: string };

export type BookingQuestionsProps = {
  heading: string;
  items: QA[];
  button?: Link;
};

const actionClass =
  "inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function BookingQuestions({ heading, items, button }: BookingQuestionsProps) {
  const still = useReducedMotion();
  return (
    <LazyMotion features={domAnimation} strict={false}>
      <section className="bg-card font-sans text-card-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.div
            initial={still ? false : { opacity: 0, y: 24 }}
            whileInView={still ? undefined : { opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.3 }}
            transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
            className="flex flex-col gap-6 border-t-2 border-foreground pt-8 sm:flex-row sm:items-end sm:justify-between"
          >
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{heading}</h2>
            {button ? (
              <a href={button.href} className={actionClass}>
                {button.label}
              </a>
            ) : null}
          </m.div>
          <dl className="mt-8 grid gap-6 md:grid-cols-2">
            {items.map((item, i): ReactNode => (
              <m.div
                key={item.q}
                initial={still ? false : { opacity: 0, y: 24 }}
                whileInView={still ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.5, delay: still ? 0 : i * 0.08, ease: [0.22, 1, 0.36, 1] }}
                className={
                  i === 0
                    ? "md:col-span-1 md:border-r md:border-border md:pr-8"
                    : "min-w-0 md:pt-6"
                }
              >
                <dt className="font-display text-h3 font-bold text-balance wrap-break-word">{item.q}</dt>
                <dd className="mt-3 max-w-text text-body text-pretty text-muted-foreground">{item.a}</dd>
              </m.div>
            ))}
          </dl>
        </div>
      </section>
    </LazyMotion>
  );
}

